    PublicProductsController_list: {
        parameters: {
            query?: {
                /** @description Opaque cursor. Belongs to one combination of search, filters and sort. */
                pageToken?: string;
                /** @description Maximum 24. */
                pageSize?: number;
                /** @description Defaults to newest, which is publishedAt descending. */
                sort?: "newest" | "price_asc" | "price_desc" | "name_asc" | "name_desc";
                /** @description Restricts the page to products whose featured flag matches. ONLY the exact strings true and false are accepted: anything else answers 400 product_filter_invalid, because silently treating ?featured=1 as no filter would put the whole catalogue on a home page that asked for a handful. Omitting it is not the same as false: absent means no filter at all. It is applied inside the authoritative query, before paging, so a 200 is still a full page or the real end. It belongs to the page token like every other filter: a cursor issued with featured=true is rejected with product_cursor_invalid when replayed without it or with featured=false. */
                featured?: boolean;
                availability?: "in_stock" | "out_of_stock";
                /** @description Normalised value of the size axis across the active variants. */
                size?: string;
                /** @description Normalised value of the finish axis across the active variants. */
                finish?: string;
                /** @description Type slug. */
                productType?: string;
                /** @description Category slug, exactly as published in the facets. */
                category?: string;
                /** @description Single search term, 2 characters or more; longer terms are truncated to 20. Matches a prefix of the product name. */
                q?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["PublicProductPageDto"];
                };
            };
            /** @description product_invalid, product_filter_invalid or product_cursor_invalid */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponseDto"];
                };
            };
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ErrorResponseDto"];
                };
            };
        };
    };
